    {
        let mut entry = entry.map_err(|e| ForgeError::io("read bundle entry", e))?;
        let path = entry
            .path()
            .map_err(|e| ForgeError::io("entry path", e))?
            .to_string_lossy()
            .into_owned();
        let mut data = Vec::new();
        entry
            .read_to_end(&mut data)
            .map_err(|e| ForgeError::io("read entry bytes", e))?;
