fn ensure_trusted_dir(parent: &Path, name: &str) -> Result<PathBuf, ForgeError> {
    let next = parent.join(name);
    match fs::symlink_metadata(&next) {
        Ok(md) if md.file_type().is_symlink() => {
            Err(ForgeError::UnsafePath(format!("{} is a symlink", name)))
        }
        Ok(md) if !md.is_dir() => {
            Err(ForgeError::UnsafePath(format!("{} is not a directory", name)))
        }
        Ok(_) => {
            // exists as a directory; verify canonical path stays under parent
            let canonical = next.canonicalize()
                .map_err(|e| ForgeError::io(format!("canonicalize {name}"), e))?;
            if !canonical.starts_with(parent) {
                return Err(ForgeError::UnsafePath(format!("{name} escapes root")));
            }
            Ok(canonical)
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            fs::create_dir_all(&next).map_err(|e| ForgeError::io(format!("create {name}"), e))?;
            // re-canonicalize to resolve any FS-side normalization
            let canonical = next.canonicalize()
                .map_err(|e| ForgeError::io(format!("canonicalize new {name}"), e))?;
            Ok(canonical)
        }
        Err(e) => Err(ForgeError::io(format!("inspect {name}"), e)),
    }
}
```

