The cleanest implementation: walk imports via DFS, treating `from_module` as an opaque edge target. For each module's imports, recurse up to MAX_IMPORT_DEPTH. Track visited set to avoid cycles. If recursion depth exceeds MAX_IMPORT_DEPTH, reject.

```rust
fn max_import_depth(
    entry: &str,
    asts: &BTreeMap<String, domainforge_core::parser::ast::Ast>,
) -> Result<usize, ForgeError> {
    fn visit(
        current: &str,
        depth: usize,
        asts: &BTreeMap<String, domainforge_core::parser::ast::Ast>,
        visiting: &mut Vec<String>,
    ) -> Result<usize, ()> {
        if depth > MAX_IMPORT_DEPTH {
            return Err(());
        }
        if visiting.iter().any(|m| m == current) {
            return Ok(depth); // cycle: domainforge-core reports it separately
        }
        let Some(ast) = asts.get(current) else {
            return Ok(depth); // unresolved: domainforge-core reports it
        };
        visiting.push(current.to_string());
        let mut max = depth;
        for import in &ast.imports {
            let child_depth = visit(&import.from_module, depth + 1, asts, visiting)?;
            if child_depth > max { max = child_depth; }
        }
        visiting.pop();
        Ok(max)
    }
    let mut visiting = Vec::new();
    visit(entry, 0, asts, &mut visiting).map_err(|_| ())
}
```

