fn push_tree(
    builder: &mut tar::Builder<&mut Vec<u8>>,
    src_dir: &Path,
    arc_prefix: &str,
    files: &mut Vec<BundleFile>,
) -> Result<(), ForgeError> {
    if !src_dir.is_dir() {
        return Ok(());
    }
    for entry in fs::read_dir(src_dir).map_err(|e| ForgeError::io("read artifacts dir", e))? {
        let entry = entry.map_err(|e| ForgeError::io("dir entry", e))?;
        let path = entry.path();
