/// Path where an imported template lives before adoption.
/// `<root>/.sea-forge/imported/<cell_id>/templates/<name>@<version>.yaml`
pub fn imported_template_path(root: &Path, cell_id: &str, name: &str, version: &str) -> PathBuf {
