fn append_raw(builder: &mut tar::Builder<&mut Vec<u8>>, path: &str, data: &[u8]) {
    let mut hdr = tar::Header::new_gnu();
    hdr.set_size(data.len() as u64);
    hdr.set_mode(0o644);
    // set_path can reject exotic names; fall back to the GNU longname field via
    // the entry-name bytes so the archive still carries the intended manifest.
    if hdr.set_path(path).is_err() {
